(()=>{'use strict';document.addEventListener('DOMContentLoaded',()=>{
const $=id=>document.getElementById(id);if(!$('certificateForm'))return;
const templates={associate:{name:'Associate Consultant',area:'strategischer und operativer Einkauf',past:'Zu den Aufgaben gehörten die Unterstützung bei der Analyse von Einkaufsdaten und Prozessen, die Recherche zu Beschaffungsmärkten und Lieferanten sowie die Aufbereitung von Projektergebnissen. Die Mitarbeit bei Ausschreibungen, die Vorbereitung von Workshops und die Dokumentation von Arbeitsergebnissen ergänzten den Aufgabenbereich.',present:'Zu den Aufgaben gehören die Unterstützung bei der Analyse von Einkaufsdaten und Prozessen, die Recherche zu Beschaffungsmärkten und Lieferanten sowie die Aufbereitung von Projektergebnissen. Die Mitarbeit bei Ausschreibungen, die Vorbereitung von Workshops und die Dokumentation von Arbeitsergebnissen ergänzen den Aufgabenbereich.'},consultant:{name:'Consultant',area:'strategischer und operativer Einkauf',past:'Der Aufgabenbereich umfasste die eigenständige Bearbeitung abgegrenzter Aufgabenpakete in Einkaufsprojekten, die Analyse von Bedarfen, Lieferanten und Beschaffungsmärkten sowie die Entwicklung von Verbesserungsvorschlägen. Hinzu kamen die Durchführung und Auswertung von Ausschreibungen, die Vorbereitung von Verhandlungen und die Abstimmung der Ergebnisse mit Kundinnen und Kunden.',present:'Der Aufgabenbereich umfasst die eigenständige Bearbeitung abgegrenzter Aufgabenpakete in Einkaufsprojekten, die Analyse von Bedarfen, Lieferanten und Beschaffungsmärkten sowie die Entwicklung von Verbesserungsvorschlägen. Hinzu kommen die Durchführung und Auswertung von Ausschreibungen, die Vorbereitung von Verhandlungen und die Abstimmung der Ergebnisse mit Kundinnen und Kunden.'},senior:{name:'Senior Consultant',area:'strategischer Einkauf und Beschaffungsoptimierung',past:'Zu den Aufgaben gehörten die fachliche Steuerung anspruchsvoller Arbeitspakete in Einkaufsprojekten, die Entwicklung von Beschaffungsstrategien sowie die Identifikation und Umsetzung von Optimierungspotenzialen. Das Aufgabenfeld umfasste die Begleitung von Ausschreibungen und Verhandlungen, das Stakeholdermanagement und die Qualitätssicherung von Analysen, Entscheidungsvorlagen und Projektergebnissen.',present:'Zu den Aufgaben gehören die fachliche Steuerung anspruchsvoller Arbeitspakete in Einkaufsprojekten, die Entwicklung von Beschaffungsstrategien sowie die Identifikation und Umsetzung von Optimierungspotenzialen. Das Aufgabenfeld umfasst die Begleitung von Ausschreibungen und Verhandlungen, das Stakeholdermanagement und die Qualitätssicherung von Analysen, Entscheidungsvorlagen und Projektergebnissen.'},managing:{name:'Managing Consultant',area:'Einkaufsberatung und Projektsteuerung',past:'Der Aufgabenbereich umfasste die eigenverantwortliche Steuerung von Kundenprojekten im Einkauf, die Strukturierung von Projektzielen und Arbeitspaketen sowie die Abstimmung mit den relevanten Stakeholdern. Zu den Schwerpunkten gehörten die Entwicklung und Umsetzung von Beschaffungsstrategien, die Steuerung von Ausschreibungen und Verhandlungen sowie die Qualitätssicherung und adressatengerechte Kommunikation der Projektergebnisse.',present:'Der Aufgabenbereich umfasst die eigenverantwortliche Steuerung von Kundenprojekten im Einkauf, die Strukturierung von Projektzielen und Arbeitspaketen sowie die Abstimmung mit den relevanten Stakeholdern. Zu den Schwerpunkten gehören die Entwicklung und Umsetzung von Beschaffungsstrategien, die Steuerung von Ausschreibungen und Verhandlungen sowie die Qualitätssicherung und adressatengerechte Kommunikation der Projektergebnisse.'}};
const row=document.createElement('div');row.className='template-row';row.innerHTML='<label>Positionsvorlage<select id="positionTemplate"><option value="">Individuell / vorhandener Text</option></select></label><button type="button" class="secondary" id="applyPositionTemplate">Vorlage für Position und Aufgaben übernehmen</button><p class="editor-hint">Ersetzt Position, Einsatzbereich und Aufgaben nach Bestätigung. Alle Texte bleiben frei bearbeitbar.</p>';$('area').closest('label').before(row);Object.entries(templates).forEach(([key,t])=>$('positionTemplate').add(new Option(t.name,key)));
let applied=null,priorKind=$('kind').value;
$('applyPositionTemplate').onclick=()=>{const key=$('positionTemplate').value,t=templates[key];if(!t){$('certificateStatus').textContent='Bitte zuerst eine Positionsvorlage wählen.';return;}if(!confirm('Position, Einsatzbereich und Tätigkeitsbeschreibung durch die Vorlage „'+t.name+'“ ersetzen?'))return;$('position').value=t.name;$('area').value=t.area;$('duties').value=$('kind').value==='interim'?t.present:t.past;applied=key;priorKind=$('kind').value;$('duties').dispatchEvent(new Event('input',{bubbles:true}));};
$('kind').addEventListener('change',()=>{const t=templates[applied];if(t&&$('duties').value===(priorKind==='interim'?t.present:t.past))$('duties').value=$('kind').value==='interim'?t.present:t.past;priorKind=$('kind').value;});
const word=document.createElement('button');word.type='button';word.id='certificateWord';word.className='secondary';word.textContent='Word exportieren (.docx)';$('certificatePrint').after(word);
word.onclick=()=>window.NexusPreflight.run(async()=>{try{word.disabled=true;$('certificateStatus').textContent='Word-Dokument wird erstellt …';if(!window.docx||!window.createNexusWord)throw Error('Die Word-Komponente ist noch nicht geladen. Bitte die App online neu öffnen.');const root=$('certificatePreview'),paragraphs=[...root.children].filter(e=>e.tagName==='P').map(e=>e.textContent),issue=paragraphs.pop();const data={title:root.querySelector('h1').textContent,addressee:root.querySelector('address').textContent,paragraphs,issue,signature:[...root.querySelectorAll('.signature p')].map(e=>e.textContent).filter(s=>!/^_+$/.test(s.trim()))};const response=await fetch('../nexus-logo.png');if(!response.ok)throw Error('Logo konnte nicht geladen werden.');const blob=await window.createNexusWord(window.docx,data,new Uint8Array(await response.arrayBuffer()));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='neXus_'+data.title+'.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('certificateStatus').textContent='Word-Dokument bereitgestellt. In Word bleiben alle Texte bearbeitbar.';}catch(err){$('certificateStatus').textContent=err.message;}finally{word.disabled=false;}});
});})();
